<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\Booking; use App\Models\Service; use App\Models\GalleryItem; use App\Models\Testimonial; use App\Models\AdminNotification; use Illuminate\Support\Facades\DB; use Illuminate\View\View;
class DashboardController extends Controller { public function __invoke():View{$today=now()->toDateString();$stats=['today'=>Booking::whereDate('appointment_date',$today)->whereIn('status',['pending','confirmed'])->count(),'pending'=>Booking::where('status','pending')->count(),'confirmed'=>Booking::where('status','confirmed')->count(),'services'=>Service::count(),'gallery'=>GalleryItem::count(),'testimonials'=>Testimonial::count(),'revenue'=>Booking::whereIn('status',['confirmed','completed'])->sum('total_price')];$notifications=AdminNotification::with('booking')->latest()->limit(10)->get();$unreadCount=AdminNotification::whereNull('read_at')->count();$upcoming=Booking::with('service')->whereDate('appointment_date','>=',$today)->whereIn('status',['pending','confirmed'])->orderBy('appointment_date')->orderBy('appointment_time')->limit(8)->get();$statusCounts=Booking::query()->select('status',DB::raw('COUNT(*) as total'))->groupBy('status')->pluck('total','status');$monthly=Booking::query()->selectRaw('DATE_FORMAT(appointment_date, "%Y-%m") as month_key, COUNT(*) as total, SUM(CASE WHEN status IN ("confirmed","completed") THEN total_price ELSE 0 END) as revenue')->whereDate('appointment_date','>=',now()->subMonths(5)->startOfMonth())->groupBy('month_key')->orderBy('month_key')->get();$chartStatus=['labels'=>['En attente','Confirmés','Terminés','Annulés','Refusés'],'data'=>[(int)($statusCounts['pending']??0),(int)($statusCounts['confirmed']??0),(int)($statusCounts['completed']??0),(int)($statusCounts['cancelled']??0),(int)($statusCounts['rejected']??0)]];$chartMonthly=['labels'=>$monthly->map(fn($m)=>$m->month_key)->all(),'bookings'=>$monthly->map(fn($m)=>(int)$m->total)->all(),'revenue'=>$monthly->map(fn($m)=>(float)$m->revenue)->all()];return view('admin.dashboard',compact('stats','upcoming','notifications','unreadCount','chartStatus','chartMonthly'));} }
